    "question": "森林保全と山地災害に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　森林の崩壊防止機能は、樹冠で雨滴が持つ運動エネルギーを減少させる効果によるものである。このような機能は、斜面の土砂や岩盤といった地中内にすべり面が形成される表層崩壊、深層崩壊、地すべりに有効である。\nB　森林の水源涵養機能は、雨水の樹冠遮断と樹木による保水により下流河川の洪水流量だけでなく渇水時流出量を減少させるものである。そのため、荒廃山地を緑化することで水源涵養機能の回復が期待できる。\nC　森林の崩壊防止機能を長期間維持するには、間伐や択伐よりも大規模皆伐が有効である。成長が盛んな20年生以下の森林では崩壊が発生しづらいことが、森林伐採と表層崩壊発生件数の統計的な調査から明らかとなっている。\nD　山地斜面で崩壊が発生した後、崩壊地の侵食や拡大を防ぐ目的で緑化が図られることがある。その際、土留工、筋工などの構造物を設置し、土砂の移動を抑制して植生が生育しやすい条件を作り、植生の自然侵入の促進又は樹木の植栽等が行われる。",
