    "difficulty": 3,
    "question": "次は、斜面侵食と森林の侵食防止機能に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n降雨による表面侵食は、通常、雨滴侵食と地表流による侵食の二つの過程に分けられる。雨滴侵食は、表面侵食の第一段階で、雨滴の［A］力により露出した土層表面の土粒子が剥離し、分散し、飛散するもので、これには浸透水による土層の膨軟化も作用している。\n雨滴の［A］には、土の孔隙構造を破壊し土層表面を締め固める作用も認められる。さらに、分散した細粒土が土層内の大中孔隙を目詰まりさせる作用も存在するので、土層表面の透水性が低下し、豪雨時に地表流が発生する。\n地表流が発生すると、土粒子の剥離、移動が起こる。また、雨滴侵食で飛散した土粒子も地表流で運搬される。これが表面侵食の第二段階である。通常この侵食は雨水が集中する多数の溝状の流路内で行われ、［B］の形を取る。斜面下部で溝状の流路網が集中し、［B］は発達して［C］となる。この場合、侵食土量は飛躍的に増加する。\n森林は、［D］あるいは林床植生の存在によって土層表面を保護することにより、雨滴侵食を防ぐ。豊かな森林土壌をもつ健全な森林は、表面侵食防止の機能をもつ。豊かな森林土壌とは、構造の発達した鉱物質土壌のみでなく、それを保護する［D］も十分発達していることである。",
