    "question": "我が国の森林整備の取組に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは、「令和5年度 森林・林業白書（令和6年6月4日公表）」による。\n\nA　農林水産大臣は、森林法に基づき、5年ごとに10年を一期とする全国森林計画を策定することとされている。同計画では、全国の森林を対象として、森林の適正な管理を図りながら森林資源の持続的な利用を一層推進して林業・木材産業の成長産業化に取り組む「グリーン成長」を実現することとしている。\nB　森林の伐採の実態や更新状況を把握するため、森林所有者等が立木の伐採及び伐採後の造林を行おうとする際は、森林法に基づき、あらかじめ市町村長に対して伐採及び造林の届出を行うこととされている。また、同法に基づき市町村長は市町村森林整備計画を立てることとされており、重視すべき機能に応じて各市町村が主体的に設定したゾーニングや路網の計画を図示している。\nC　森林・林業基本計画では、傾斜や作業システムに応じ、林道と森林作業道を適切に組み合わせた路網の整備を推進するとともに、専門的な人材の減少を踏まえた路網規格の簡素化を図ることとしている。同計画では、林道等の望ましい総延長の目安である25万 kmの整備を令和17（2035）年までに全て完了することとしている。\nD　J-クレジット制度において、森林整備を行うプロジェクト実施者は森林吸収量（森林による二酸化炭素吸収量）の認証を受けてクレジットを発行し、企業や団体等がそれを購入することにより、更なる森林整備を後押ししている。森林吸収分野においては、令和3（2021）年以降には吸収量算定に係る現地調査に代えて航空レーザ計測データの活用を可能とするなどの制度改正が行われており、令和5（2023）年度は、新規登録件数及びクレジット認証量が制度発足以来最大となった。",
