      "オ": "国有林野は、我が国の国土面積の約2割、森林面積の約3割に相当する面積を有し、奥地脊梁山地や水源地域に広く分布しており、国土の保全、水源の涵養等の公益的機能の発揮に重要な役割を果たしている。また、人工林、原生的な天然林等の多様な生態系を有し、希少種を含む様々な野生生物の生育・生息の場となっている。"
