      "ウ": "「保健・レクリエーション機能」とは、芸術、伝統文化などの活動の場を提供する機能のことである。国有林においては、歴史的に重要な木造建造物や各地の祭礼行事、伝統工芸等の次代に引き継ぐべき木の文化を守るため、「社会貢献の森」を設定している。",
