      "オ": "内閣府が令和5（2023）年に行った森林と生活に関する世論調査によると、森林の有する多面的機能のうち森林に期待する働きについて、回答者の割合が高いものから順に「水源涵養」、「野生動植物生息の場」、「山地災害防止」であった。また、「特用林産物生産」とする回答者の割合の順位は、平成5（1993）年の調査以降、4番目に位置している。"
