    "difficulty": 3,
    "question": "次は、森林の生態系サービスに関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\nForest loss has negative direct and indirect impacts on human health, although data are limited (comparative datasets do not exist at the global level) and the risks of emerging infectious diseases (EIDs) associated with forest ecosystems are poorly studied. Most research tends to focus on a few specific diseases (and known reservoirs＊1 or hosts) rather than attempting to fully understand all relevant host-pathogen-environment dynamics in an ecosystem. Nevertheless, the majority (60 percent) of EIDs are caused by pathogens that have a non-human animal source (i.e. are zoonotic), and nearly three-quarters (71.8 percent) of such zoonotic EIDs originate in ［A］. Landscape change and biodiversity loss involve major shifts in the ecology of pathogens and the wildlife habitats or species they use as hosts and reservoirs, thus altering disease patterns. Moreover, such changes tend to put people physically in closer contact with pathogens, and the wildlife trade can bring pathogens into the human population. ［B］ change (comprising deforestation, human settlement in primarily wildlife habitat, the spread of crop and livestock production, and urbanization) is a globally significant driver of pandemics; it is estimated to have caused the emergence of more than 30 percent of new diseases reported since 1960.\n\nDeforestation and forest fragmentation also bring ［C］ and livestock into closer contact with wildlife, increasing human-wildlife conflicts and the risk of disease transmission between them. Deforestation is an important factor in the spread of vector-borne diseases (i.e. diseases, such as malaria, that are transmitted by vector species between susceptible species). A recent study found that 15 percent of about 250 analysed EIDs were linked to forests, several of which (e.g. Ebola and human immunodeficiency＊2 virus infection/acquired immunodeficiency syndrome) are particularly harmful to human health and economies. Deforestation, particularly in ［D］ regions, has been associated with an increase in infectious diseases such as dengue fever, malaria and yellow fever.\n\n＊1　reservoirs：保有宿主\n＊2　immunodeficiency：免疫不全",
