    "explanation": "ビッターリッヒ法は一定の視角を超える木を数え、断面積定数を掛けて単位面積当たりの胸高断面積を推定する。ストランド法は抽出の基準を点から線に変え、胸高断面積や円柱体積を推定できる。",
