      "ウ": "土中の水のうち、水の表面張力による毛管現象により土の間隙内に吸い上げられた水を毛管水という。冬季に発生する凍上は、毛管現象が継続的に起こる土で生じ、液状化により地盤沈下を起こす現象である。凍上は、毛管上昇高が大きく、透水性が大きい砂質土で生じやすい。",
