    "difficulty": 3,
    "question": "砂防関係施設の点検、長寿命化に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 砂防関係施設の点検には、定期点検、臨時点検、詳細点検がある。これらのうち、臨時点検は、豪雨や地震が発生した際、緊急的に砂防関係施設の機能の低下等の状況を把握するために実施する。臨時点検を迅速かつ的確に実施するために、事前に点検範囲の決定方法の設定等に留意した点検計画を策定しておくことが望ましい。\nB. 砂防関係施設の定期点検は、機能の低下等の状況を把握することで、施設の健全度評価を行うために1年に1回実施することが求められている。点検は、目視又は無人航空機（UAV）により実施するが、砂防関係施設のうち、砂防堰堤は全国で6万基以上あり、数が膨大である。そのため、1年に1回の実施が困難な場合は周辺施設の点検結果から推定することとしている。\nC. 砂防関係施設の健全度評価を行う場合、現在の設計基準より以前の基準に基づいて設計・施工されたものは安全性が担保されていないという評価になる。長寿命化対策の検討に際しては、現在の設計基準を満たす工法のうち、工事費用が最も少なくなる工法を選定することで、適切に対策を実施することになっている。\nD. 砂防関係施設の予防保全型維持管理では、30～50年程度の中期年次計画と10年程度の短期年次計画を策定することを基本としている。中期年次計画は、対策が必要となる施設を抽出して概略的な箇所数等を記載し、短期年次計画は、対策を実施する具体的な箇所を抽出するとともに、詳細な事業計画を記載することが望ましい。",
    "choices": {
      "ア": "A、B",
      "イ": "A、C",
      "ウ": "A、D",
      "エ": "B、C",
      "オ": "C、D"
    },
