    "question": "図Ⅰは土の種類と締固め曲線の関係、図Ⅱは締固め曲線と締め固めた土の力学的性質との関係を表したものである。A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n図Ⅰに示されているように、［A］では、最適含水比（ωₒₚₜ）が低く、最大乾燥密度（ρ_d max）は高い。逆に、［B］では、最適含水比が高く、最大乾燥密度は低い。\n\nまた、一般に、締め固めた土の［C］は、乾燥密度が高いほど大きく、図Ⅱに示されているように、最適含水比よりわずかに乾燥側で最大となる。\n\n一般に、多くの土では、含水比が乾燥側の場合、締固め仕事量が大きくなるほど乾燥密度は大きくなり、［C］も増大する。一方、含水比が湿潤側の場合は、ある締固め仕事量に達すると［C］は増大しなくなり、さらに仕事量が増加すると［C］が低下することもある。この現象は［D］と呼ばれる。",
