    "difficulty": 3,
    "question": "土石流・流木対策施設に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 高さ15 m未満の不透過型砂防堰堤の設計における安定計算では、土石流時については静水圧、堆砂圧及び土石流荷重を、洪水時については静水圧を、平常時については地震時慣性力及び地震時動水圧をそれぞれ考慮する。土石流時の場合、土石流荷重は堰堤本体に最も危険な状態とし、堆砂地が空の状態で土石流が直撃したケースを想定する。\nB. 不透過型砂防堰堤の設計流量は、「洪水時における土砂含有を考慮しない清水の流量」と、「土石流時における土石流ピーク流量」とする。前者は、計画規模の年超過確率の降雨量と既往最大の降雨量を比較した小さい方の値から算出される。後者は、渓流内の全ての支渓から同時に土砂が流出する場合の流出土砂量に基づいて求めることを基本とする。\nC. 不透過型砂防堰堤の基礎は岩着することが望ましいが、岩着が望めない場合にはフローティング基礎としてもよい。ただし、その場合、砂防堰堤の堰堤高は15 m未満であることを原則とする。なお、支持地盤が軟弱地盤である場合又は所定の支持力が得られない場合には、基礎処理を施すものとする。\nD. 土石流・流木対策施設が機能を発揮するよう、土石流等発生後の点検や定期点検において堆砂状況等を確認し、必要に応じて除石及び流木の除去を行う。また、土石流・流木処理計画において除石等が必要となる場合は、搬出路を含めてあらかじめ搬出方法を検討しておくものとする。",
