    "question": "xy 平面上において、y＝x³−5x＋3 で表される曲線を C とする。また、曲線 C に接しており、y＝−2x＋1 で表される直線を l とする。この曲線 C と接線 l で囲まれた部分の面積として最も妥当なのはどれか。",
