      "イ": "差を因数分解すると (x−1)²(x＋2) で、交点は x＝−2 と接点 x＝1 である。その間では曲線が上にあり、∫₋₂¹ (x³−3x＋2) dx＝27/4 となる。",
      "ウ": "曲線と接線の高さの差を積分するため、原始関数には −3x²/2 が入る。原始関数 x⁴/4−3x²/2＋2x を −2 から 1 まで評価すると 15/2 ではなく 27/4 になる。",
