    "difficulty": 3,
    "question": "山地河川における土砂移動現象やその観測手法に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 土砂の運動形式には、個別粒子がばらばらに運動する各個運搬と、粒子群が集団で移動する集合運搬とがある。河道における土砂移動現象には、土石流、土砂流、掃流、浮遊があるが、土石流は各個運搬に分類される。また、土砂移動現象の観測場所は、横断工作物がない箇所を基本とする。\nB. 山地河川における流砂観測は、流域の土砂動態の把握や、砂防事業の効果評価、総合的な土砂管理手法の検討などのために実施するものである。流砂観測では流量観測も併用し、平常時から洪水時までの幅広い条件下において、欠測なく長期間連続的に観測することが望ましい。\nC. 掃流砂は、河床に接触しながら河床上を滑動、転動又は跳躍しながら輸送される土砂成分である。山地河川の掃流砂量を求める計算式として、芦田・道上式やMeyer-Peter・Muller式が知られている。\nD. 浮遊砂は、河床材料よりも細かい成分であり、途中で大きな貯水池などがない限り、河口まで河床と接触することなく輸送される土砂成分である。浮遊砂量の観測については、浮遊砂は粒径が小さく、サンプラー等を用いて直接採取することが困難であることから、経験式を用いて流砂量を推定する手法のみを用いる。",
