    "difficulty": 3,
    "question": "次は、近年の我が国における洪水対策等に関する記述であるが、A、B、Cに当てはまるものの組合せとして最も妥当なのはどれか。\n\n洪水・内水・高潮により、想定を超える浸水被害が多発したことを受け、平成27（2015）年に水防法等の改正が行われ、［A］の洪水・内水・高潮にかかる浸水想定区域を公表することとなった。これを受け全国で、これに対応した洪水・内水・高潮ハザードマップの公表が進んだ。\n\n一方、平成27年9月の関東・東北豪雨等において逃げ遅れによる多数の死者が発生したことを受け、平成29（2017）年にも水防法の改正が行われ、洪水リスクが高い区域に存在する［B］について、避難確保計画の作成及び避難訓練の実施が新たに義務付けられた。\n\nまた、令和3（2021）年に特定都市河川浸水被害対策法の改正が行われ、都市部を流れる河川の流域において浸水が発生した場合に、生命や身体に著しい危害が生ずるおそれがある土地等を浸水被害防止区域として指定し、同区域内では［C］することとなった。\n\nこのような施策を含め、近年、気候変動による水災害リスクの増大に備え、河川管理者だけでなく流域の多くの関係者による「流域治水」の取組が全国で行われるようになった。",
