      "イ": "Aの流速は水中の粒子から反射する音波のドップラー偏移で測り、Bの水深は音波が河床まで往復する時間で求める。横断中の測位で得るCは川幅で、水深と幅で断面積を求めて流速と組み合わせる。",
      "ウ": "Aは反射波の周波数変化から得る流速で、水深ではない。水深と川幅を使って断面積を求め、その断面を流れる水の流量を算出する。",
      "エ": "音の周波数の変化から求まるAはvelocityである。河床との間の音の往復時間から求めるのはdepthで、船の横断経路から求めるのがwidthである。",
