      "オ": "支柱は、植え付けた樹木が倒れたり、風によって揺れ動かないように固定するもので、支柱の丸太と丸太の接合部分はしゅろ縄で割り縄掛けにする。一般に3本の支柱で樹木を支持する布掛支柱は大規模植込地等に適用され、ワイヤー張り支柱は樹高の高い場合に適用される。"
