      "オ": "刈込みは、樹木の樹冠を刈り、縮小させる作業であり、生垣刈込みもこの一種である。刈込みに適さない樹種もあり、マサキやハクチョウゲなどが当てはまる。刈込みは常に美観を整えるため、花木類を除き、年に5回以上行うことが望ましい。"
