    "question": "自然環境保全法に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 令和6（2024）年7月現在、自然環境保全地域は全て陸域に指定されている。また、その自然環境の保全を図るため、同地域内に指定される特別地区では、建築物などの新築や木竹の伐採等の行為は規制されているが、保全された自然環境の恩恵を国民が広く享受できるよう全ての地域で環境省による探勝路の整備が行われている。\nB. 原生自然環境保全地域は、自然環境が人の活動の影響を受けることなく原生の状態を維持しており、かつ、一定面積以上の土地の区域で、国又は地方公共団体が所有するもののうち、当該自然環境を保全することが特に必要な地域を環境大臣が指定している。このうち、南硫黄島原生自然環境保全地域は、その自然環境について厳正な保全を図るものとされ、全域が立入制限地区となっている。\nC. 平成31（2019）年に自然環境保全法の一部が改正され、さんご、海藻その他の動植物を含む自然環境が優れた状態を維持している水深200 m以内の海域を、沖合海底自然環境保全地域として新たに指定できるようになった。\nD. 一般に「緑の国勢調査」と呼ばれる自然環境保全基礎調査は、自然環境保全法に基づいて行われるものである。国は、地形、地質、植生、野生動物に関する調査その他自然環境の保全のために講ずべき施策の策定に必要な基礎調査を行うよう努めるものとされている。",
