    "question": "我が国の外来種問題に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 外来種の植物の防除に当たっては、刈り取った植物を処分するために、防除した場所から植物を運搬する際に、種子や個体の一部が漏れ出さないよう注意する必要がある。外来生物法＊1に基づき特定外来生物に指定されている生物の移動は規制されているが、地域のボランティア等による小規模な植物の防除の場合、所定の要件を満たせば手続を経ずに運搬が可能である。\nB. 平成22（2010）年に開催されたカルタヘナ議定書＊2締約国会合において採択された目標20のうちの一つである「侵略的外来種とその定着経路が特定され、優先順位が付けられ、優先度の高い種が制御され、根絶される」を達成するために、我が国では環境省が中心となり、要注意外来生物リストを平成27（2015）年3月に策定した。\nC. 外来種被害防止行動計画において、外来種とは、海外から日本に持ち込まれた生物を指し、我が国の在来種であれば、元々は分布していない場所に持ち込まれた生物については対象としていない。また、外来種は、非意図的ではなく、人間の活動に伴い意図的に生息域外に移動させられたものを指す概念である。\nD. 蝶の一種であるアカボシゴマダラは、人為的な放出が原因と考えられる個体が、2000年代に入ったあたりから関東地方で急速に定着が進み、現在は関東地方以外にも愛知県や京都府などでも確認されるようになっている。オオムラサキなどの近縁種との競合が危惧されることから、特定外来生物に指定されている。\n\n＊1 特定外来生物による生態系等に係る被害の防止に関する法律\n＊2 生物の多様性に関する条約のバイオセーフティに関するカルタヘナ議定書",
