    "difficulty": 3,
    "question": "次は、木材の力学特性に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n［A］MC_fs＊ wood changes dimension as it gains moisture (swells) or loses moisture (shrinks), because volume of the cell wall depends on the amount of［B］water. This shrinking and swelling can result in warping, checking, and splitting of the wood, which in turn can lead to decreased utility of wood products, such as loosening of tool handles, gaps in flooring, or other performance problems. Therefore, it is important that the dimensional stability be understood and considered when a wood product will be exposed to large moisture fluctuations in service.\n\nWith respect to dimensional stability, wood is an anisotropic material. It shrinks (swells) most［C］.\n（中略）\nThe combined effects of radial and tangential shrinkage can distort the shape of wood pieces because of the difference in shrinkage and the curvature of annual rings.\n（中略）\nThe shrinkage of wood is affected by a number of variables. In general, greater shrinkage is associated with［D］density. The size and shape of a piece of wood can affect shrinkage, and the rate of drying can affect shrinkage for some species.\n（中略）\nLongitudinal shrinkage of wood (shrinkage parallel to the grain) is generally quite small. Average values for shrinkage from green to ovendry are between［E］for most species of wood.\n\n＊ MC_fs：The moisture content at which only the cell walls are completely saturated but no water exists in cell lumina.",
