      "ウ": "繊維飽和点より下で寸法に影響する水は、細胞壁の結合水である。放射方向より接線方向の収縮が大きく、繊維方向は通常0.1～0.2％程度にとどまる。",
      "エ": "結合水が減って収縮するのは、細胞壁が飽和しなくなる繊維飽和点より下である。最大の収縮方向は放射方向ではなく接線方向である。",
