      "ウ": "木材は異方性材料で、繊維傾斜が板目面や柾目面の強度に及ぼす影響は大きい。繊維傾斜角は一般に、木材の圧縮強度に比べて引張強度により大きく影響を及ぼす。繊維傾斜角に対する木材の強さを表すための適合式が知られている。",
