      "オ": "木材を横架材として使用する場合には、曲げ特性は重要である。梁の3点曲げ試験の過程において、中立軸の位置は不変であり、その上側に圧縮応力、下側に引張応力が生じる。梁せいに対するスパンの比が大きくなると、せん断力による影響が無視できなくなる。"
