    "question": "木造建築物の構法や特徴に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 木造軸組構法は、合板などの面材料を使用せずに、梁・桁等の横架材と柱で建物を構成する構法であり、我が国では最も広く普及している。また、部材の接合には仕口や継手が用いられており、金物が用いられることはない。\nB. 枠組壁工法は、欧州で普及していた構法が日本向けに導入されたものである。2×4インチや2×6インチなどの枠組材により構成された枠組に合板などの面材料を釘打ちしてパネルを作り、これにより壁や床を構成する。枠組材の材料樹種は輸入材のSPF＊に限られている。\nC. 木質プレハブ工法は、合板を枠材に接着したパネルで建物を構成する壁式構造である。接着を確実に行うことで被着材どうしを一体化させることができ、枠組壁工法の釘打ちパネルよりも小さい部材断面で高い剛性・強度を発揮させることが可能である。\nD. 丸太組構法は、丸太や製材を横積みして作る壁式構造である。丸太どうしがずれないように丸太どうしの間にダボを挟んだり、壁の上下をボルトで緊結したりする必要がある。経年とともに壁の高さが低くなる現象が起こることが知られている。\n\n＊ 北米産の針葉樹で、スプルース（Spruce）、パイン（Pine）、ファー（Fir）の3樹種の総称",
