    "question": "建築基準法に基づく木造建築物の防耐火に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 防火構造とは、壁や柱等の建築物の構造のうち、火災による建築物の倒壊・延焼を防止するために、建築物の部分に必要とされる性能を有する構造である。防火構造の性能をもつ外壁においては、遮熱性が低下することから、表面材として木材を張ることはできない。\nB. 木質耐火部材には、木材を石膏ボードで被覆したものや、モルタル等の燃え止まり層を備えたもの、鉄骨を木材で被覆したものなどがある。さらに、建築基準法施行令の改正（令和5（2023）年4月施行）において新たに基準が設定された、1.5時間の耐火性能を有する木質耐火部材の開発が進められている。\nC. 建築物内の火災は、火炎が天井を這うように燃え広がる性質があることから、建築物の用途や防火上の地域区分、建物の高さにより、内装制限の対象となる建築物が示されている。例えば、病院の居室の壁には、その規模に関わらず原則木材は使用できないが、床面から高さ1.2 m以下の腰壁部分については不燃処理をした木材に限り使用が可能である。\nD. 燃えしろ設計とは、部材表面から燃えしろを除いた残存断面を用いて許容応力度計算を行い、表面部分が焼損しても構造耐力上支障のないことを確かめ、火災時の倒壊を防止する設計である。燃えしろ設計を用いる場合は、日本農林規格（JAS）に適合している木質材料を用いる必要がある。",
