      "オ": "令和7（2025）年施行予定の建築基準法施行令の改正に伴い、小規模な木造建築物の建築確認申請において、構造関係規定の審査が免除される特例の範囲が拡大される。他方、中大規模建築物においては、設計時に構造計算が求められるため、JAS製材の必要性が高まっている。JAS製材（機械等級区分構造用製材）の認証工場数は増加傾向にあり、令和4年度には1,000を超えた。"
