      "イ": "厚みのある木材が乾燥する場合、乾燥初期にまず表層が収縮し、内層は収縮しない。そのため、表層で圧縮応力、内層で引張応力が生じる。このように、乾燥に伴って表層と内層で収縮に相対的な差が生じる現象をヒステリシスという。",
      "ウ": "木材には収縮異方性があり、心持ち角材の乾燥では、放射方向と接線方向の収縮率の違いが原因となって乾燥初期に内部割れが発生する。このような割れの発生を抑制する手段として、背割りが有効であり、背割りの溝が乾燥に伴って狭まることで、角材の他の面における割れを抑制する。",
