      "イ": "南北に長い我が国では、気象環境の地域差が大きい。そこで、地域差を考慮した耐候処理を検討するため、木材単板を各地域で垂直暴露し、その質量減少率と気象データとの相関関係から算出した、インデックスによる木材の気象劣化マップが用いられる。",
      "ウ": "木材の表層では、太陽光による激しい光化学反応が起きる。太陽光の照射により、アミド基などの光吸収基をもつリグニンは分解され水溶性成分となり溶脱することに加え、セルロースが不安定化することで劣化が進む。",
